ALTER TABLE public.orders ADD COLUMN order_number text, ADD COLUMN order_date date NOT NULL DEFAULT ((now() AT TIME ZONE 'Asia/Jakarta')::date), ADD COLUMN invoice_state text NOT NULL DEFAULT 'draft' CHECK(invoice_state IN ('draft','pending','issued','cancelled')), ADD COLUMN issued_at timestamptz, ADD COLUMN brand_snapshot jsonb, ADD COLUMN discount_type text NOT NULL DEFAULT 'percent' CHECK(discount_type IN ('percent','amount')), ADD COLUMN discount_value numeric NOT NULL DEFAULT 0 CHECK(discount_value>=0 AND discount_value<>'NaN'::numeric), ADD COLUMN tax_enabled boolean NOT NULL DEFAULT false, ADD COLUMN tax_rate numeric NOT NULL DEFAULT 0 CHECK(tax_rate>=0 AND tax_rate<=100), ADD COLUMN approved_fingerprint text;
ALTER TABLE public.order_items ADD COLUMN discount_type text NOT NULL DEFAULT 'percent' CHECK(discount_type IN ('percent','amount')), ADD COLUMN discount_value numeric NOT NULL DEFAULT 0 CHECK(discount_value>=0 AND discount_value<>'NaN'::numeric);
CREATE UNIQUE INDEX orders_order_number_unique ON public.orders(tenant_id,order_number) WHERE order_number IS NOT NULL;
CREATE TABLE public.document_sequences(tenant_id uuid NOT NULL REFERENCES public.tenants(id),client_code text NOT NULL,document_type text NOT NULL CHECK(document_type IN ('order','invoice','quotation')),sequence bigint NOT NULL DEFAULT 0 CHECK(sequence>=0),PRIMARY KEY(tenant_id,client_code,document_type));
GRANT SELECT ON public.document_sequences TO authenticated; GRANT ALL ON public.document_sequences TO service_role;
ALTER TABLE public.document_sequences ENABLE ROW LEVEL SECURITY;
CREATE POLICY sequences_read ON public.document_sequences FOR SELECT TO authenticated USING(public.can_access_tenant_module(tenant_id,'orders') OR public.can_access_tenant_module(tenant_id,'quotations'));
CREATE TABLE public.quotations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),client_id uuid,client_name text NOT NULL CHECK(length(btrim(client_name))>0),client_address text,quotation_number text NOT NULL,document_date date NOT NULL DEFAULT ((now() AT TIME ZONE 'Asia/Jakarta')::date),valid_until date,due_date date,notes text,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','terkirim','disetujui','ditolak','kedaluwarsa')),discount_type text NOT NULL DEFAULT 'percent' CHECK(discount_type IN ('percent','amount')),discount_value numeric NOT NULL DEFAULT 0 CHECK(discount_value>=0 AND discount_value<>'NaN'::numeric),tax_enabled boolean NOT NULL DEFAULT false,tax_rate numeric NOT NULL DEFAULT 0 CHECK(tax_rate>=0 AND tax_rate<=100),approved_fingerprint text,converted_order_id uuid,brand_snapshot jsonb,created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,deleted_by uuid,delete_reason text,UNIQUE(tenant_id,id),UNIQUE(tenant_id,quotation_number),FOREIGN KEY(tenant_id,client_id) REFERENCES public.clients(tenant_id,id),FOREIGN KEY(tenant_id,converted_order_id) REFERENCES public.orders(tenant_id,id));
GRANT SELECT,INSERT,UPDATE ON public.quotations TO authenticated; GRANT ALL ON public.quotations TO service_role;
ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY;
CREATE POLICY quotations_select ON public.quotations FOR SELECT TO authenticated USING(deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,'quotations'));
CREATE POLICY quotations_insert ON public.quotations FOR INSERT TO authenticated WITH CHECK(public.can_access_tenant_module(tenant_id,'quotations'));
CREATE POLICY quotations_update ON public.quotations FOR UPDATE TO authenticated USING(deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,'quotations')) WITH CHECK(public.can_access_tenant_module(tenant_id,'quotations'));
CREATE POLICY quotations_delete ON public.quotations FOR DELETE TO authenticated USING(false);
CREATE TABLE public.quotation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),quotation_id uuid NOT NULL,item_name text NOT NULL CHECK(length(btrim(item_name))>0),qty numeric NOT NULL CHECK(qty>0 AND qty<>'NaN'::numeric),price numeric NOT NULL CHECK(price>=0 AND price<>'NaN'::numeric),unit text NOT NULL DEFAULT 'pcs',position integer NOT NULL DEFAULT 1,discount_type text NOT NULL DEFAULT 'percent' CHECK(discount_type IN ('percent','amount')),discount_value numeric NOT NULL DEFAULT 0 CHECK(discount_value>=0 AND discount_value<>'NaN'::numeric),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,deleted_by uuid,delete_reason text,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,quotation_id) REFERENCES public.quotations(tenant_id,id));
GRANT SELECT,INSERT,UPDATE ON public.quotation_items TO authenticated; GRANT ALL ON public.quotation_items TO service_role;
ALTER TABLE public.quotation_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY quotation_items_select ON public.quotation_items FOR SELECT TO authenticated USING(deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,'quotations'));
CREATE POLICY quotation_items_insert ON public.quotation_items FOR INSERT TO authenticated WITH CHECK(public.can_access_tenant_module(tenant_id,'quotations'));
CREATE POLICY quotation_items_update ON public.quotation_items FOR UPDATE TO authenticated USING(deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,'quotations')) WITH CHECK(public.can_access_tenant_module(tenant_id,'quotations'));
CREATE POLICY quotation_items_delete ON public.quotation_items FOR DELETE TO authenticated USING(false);
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),order_id uuid NOT NULL,amount numeric NOT NULL CHECK(amount>0 AND amount<>'NaN'::numeric),payment_date date NOT NULL DEFAULT ((now() AT TIME ZONE 'Asia/Jakarta')::date),method text NOT NULL CHECK(method IN ('transfer','tunai','kartu','lainnya')),reference text,notes text,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),voided_at timestamptz,voided_by uuid,void_reason text,FOREIGN KEY(tenant_id,order_id) REFERENCES public.orders(tenant_id,id),CHECK((voided_at IS NULL AND voided_by IS NULL AND void_reason IS NULL) OR (voided_at IS NOT NULL AND voided_by IS NOT NULL AND length(btrim(void_reason))>0)));
GRANT SELECT ON public.payments TO authenticated; GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_select ON public.payments FOR SELECT TO authenticated USING(public.can_access_tenant_module(tenant_id,'finance'));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),user_id uuid NOT NULL,message text NOT NULL,request_id uuid REFERENCES public.approval_requests(id),read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE(read_at) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(tenant_id=public.active_tenant_id() AND user_id=auth.uid());
CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(tenant_id=public.active_tenant_id() AND user_id=auth.uid()) WITH CHECK(tenant_id=public.active_tenant_id() AND user_id=auth.uid());
ALTER TABLE public.receivables ADD COLUMN order_id uuid,ADD COLUMN invoice_total numeric NOT NULL DEFAULT 0 CHECK(invoice_total>=0),ADD CONSTRAINT receivables_order_fk FOREIGN KEY(tenant_id,order_id) REFERENCES public.orders(tenant_id,id);
CREATE UNIQUE INDEX receivables_order_unique ON public.receivables(tenant_id,order_id) WHERE order_id IS NOT NULL;
ALTER TABLE public.tasks ADD COLUMN completed_at timestamptz;
UPDATE public.tasks SET completed_at=updated_at WHERE status='Done';
CREATE FUNCTION public.set_task_completed() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='Done' THEN IF TG_OP='INSERT' THEN NEW.completed_at:=now(); ELSIF OLD.status IS DISTINCT FROM 'Done' THEN NEW.completed_at:=now(); ELSE NEW.completed_at:=OLD.completed_at; END IF; ELSE NEW.completed_at:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER task_completed BEFORE INSERT OR UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.set_task_completed();
CREATE OR REPLACE FUNCTION public.entity_module(p_table text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE p_table WHEN 'clients' THEN 'crm' WHEN 'orders' THEN 'orders' WHEN 'order_items' THEN 'orders' WHEN 'quotations' THEN 'quotations' WHEN 'quotation_items' THEN 'quotations' WHEN 'shipments' THEN 'shipments' WHEN 'pricelist_items' THEN 'pricelist' WHEN 'payables' THEN 'finance' WHEN 'receivables' THEN 'finance' WHEN 'cash_requests' THEN 'finance' WHEN 'expenses' THEN 'finance' WHEN 'tasks' THEN 'workflow' WHEN 'team_members' THEN 'team' END $$;
CREATE OR REPLACE FUNCTION public.admin_set_modules(p_user_id uuid,p_modules text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master() OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships WHERE tenant_id=public.active_tenant_id() AND user_id=p_user_id AND status='active') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; DELETE FROM public.module_access WHERE tenant_id=public.active_tenant_id() AND user_id=p_user_id; INSERT INTO public.module_access(tenant_id,user_id,module) SELECT public.active_tenant_id(),p_user_id,m FROM unnest(COALESCE(p_modules,'{}'::text[])) m WHERE m IN ('dashboard','crm','finance','orders','quotations','shipments','pricelist','workflow','team') ON CONFLICT DO NOTHING; END $$;
INSERT INTO public.module_access(tenant_id,user_id,module) SELECT tenant_id,user_id,'quotations' FROM public.module_access WHERE module='orders' UNION SELECT tenant_id,user_id,'quotations' FROM public.user_roles WHERE role='master' ON CONFLICT DO NOTHING;
CREATE FUNCTION public.sales_write_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user NOT IN ('postgres','supabase_admin','service_role') THEN RAISE EXCEPTION 'Gunakan fungsi transaksi atomik'; END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Gunakan arsip, bukan hapus permanen'; END IF; IF TG_OP='UPDATE' AND NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN RAISE EXCEPTION 'Tenant tidak boleh diubah'; END IF; RETURN NEW; END $$;
CREATE TRIGGER sales_atomic_only BEFORE INSERT OR UPDATE OR DELETE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.sales_write_guard();
CREATE TRIGGER sales_atomic_only BEFORE INSERT OR UPDATE OR DELETE ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.sales_write_guard();
CREATE TRIGGER sales_atomic_only BEFORE INSERT OR UPDATE OR DELETE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.sales_write_guard();
CREATE TRIGGER sales_atomic_only BEFORE INSERT OR UPDATE OR DELETE ON public.quotation_items FOR EACH ROW EXECUTE FUNCTION public.sales_write_guard();
CREATE TRIGGER payment_atomic_only BEFORE INSERT OR UPDATE OR DELETE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.sales_write_guard();
CREATE TRIGGER quotation_audit AFTER INSERT OR UPDATE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.audit_business_change();
CREATE TRIGGER quotation_item_audit AFTER INSERT OR UPDATE ON public.quotation_items FOR EACH ROW EXECUTE FUNCTION public.audit_business_change();
CREATE FUNCTION public.payment_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(NEW.tenant_id,auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'payment' ELSE 'payment_void' END,'payments',NEW.id,jsonb_build_object('after',to_jsonb(NEW))); RETURN NEW; END $$;
CREATE TRIGGER payment_audit AFTER INSERT OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.payment_audit();
CREATE FUNCTION public.linked_receivable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.order_id IS NOT NULL OR (TG_OP='UPDATE' AND OLD.order_id IS NOT NULL)) AND current_user NOT IN ('postgres','supabase_admin','service_role') THEN RAISE EXCEPTION 'Piutang invoice mengikuti catatan pembayaran'; END IF; RETURN NEW; END $$;
CREATE TRIGGER linked_receivable_guard BEFORE INSERT OR UPDATE ON public.receivables FOR EACH ROW EXECUTE FUNCTION public.linked_receivable_guard();
CREATE INDEX payments_invoice_idx ON public.payments(tenant_id,order_id); CREATE INDEX quotations_list_idx ON public.quotations(tenant_id,created_at); CREATE INDEX quotation_items_parent_idx ON public.quotation_items(tenant_id,quotation_id); CREATE INDEX notifications_user_idx ON public.notifications(tenant_id,user_id,created_at);
COMMENT ON COLUMN public.orders.document_status IS 'DEPRECATED: replaced by invoice_state'; COMMENT ON COLUMN public.orders.discount_pct IS 'DEPRECATED: replaced by discount_type and discount_value';